[asy]
pair A=(4,0),B=(0,1),F1=(4-sqrt(15),1),F2=(4+sqrt(15),1),O=(4,1); real f(real x) { return 1 + sqrt(1 - (x-4)*(x-4)/16); } real g(real x) { return 1 - sqrt(1 - (x-4)*(x-4)/16);  } draw(graph(f, 0, 8) ^^ graph(g, 0, 8));
